import{_ as t,o as a,c as o,a4 as r,av as s}from"./chunks/framework.DA9C4Pbl.js";const f=JSON.parse('{"title":"External Storages","description":"","frontmatter":{"title":"External Storages","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/data/external-storages.md","filePath":"guides/data/external-storages.md"}'),n={name:"guides/data/external-storages.md"};function d(i,e,l,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="external-storages" tabindex="-1">External Storages <a class="header-anchor" href="#external-storages" aria-label="Permalink to “External Storages”">​</a></h1><p><strong>External Storages</strong> are data storages you already own — as an astronomer or as an observatory — attached to Arcsecond.local so that their content is indexed alongside the data the installation holds itself. There is no limit on the number of storages you can attach.</p><p>Attached storages are <strong>read-only</strong> for indexing: Arcsecond.local never modifies anything in them. Some kinds can also serve as the <em>destination</em> of new data on a self-hosted installation, in which case Arcsecond writes inside a folder of its own on that storage, <code>Arcsecond/</code>, and nowhere else. Credentials are provided once, then stored encrypted — see <a href="./credentials-security">Credentials &amp; Security</a>.</p><h2 id="which-storages" tabindex="-1">Which storages <a class="header-anchor" href="#which-storages" aria-label="Permalink to “Which storages”">​</a></h2><p>The table is what the code supports today, not a roadmap.</p><table tabindex="0"><thead><tr><th>Storage</th><th>Indexed</th><th>Can hold new data</th><th>Credentials</th></tr></thead><tbody><tr><td><strong>Amazon S3</strong></td><td>yes</td><td>yes</td><td><code>AWS_ACCESS_KEY_ID</code>, <code>AWS_SECRET_ACCESS_KEY</code>, <code>AWS_REGION</code>, <code>AWS_S3_BUCKET_NAME</code> — see <a href="./external-storage-aws">Creating a read-only IAM user</a></td></tr><tr><td><strong>Dropbox</strong></td><td>yes</td><td>no</td><td>an app access token, and the root folder</td></tr><tr><td><strong>FTP</strong></td><td>yes</td><td>no</td><td>host, port, user, password, root folder</td></tr><tr><td><strong>SFTP</strong></td><td>yes</td><td>yes</td><td>host, port, user, a password <em>or</em> a private key (with its passphrase), root folder</td></tr><tr><td><strong>SMB / Windows share</strong></td><td>yes</td><td>yes</td><td>host, port, share name, domain, user, password, root folder</td></tr><tr><td>Local disk (a folder on the machine)</td><td>not yet</td><td>—</td><td>—</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">What is not available</p><p>Azure, Google Drive and observatory archives (ESO, CADC, HST…) were listed as choices in earlier versions of these pages and of the application. No backend ever existed for them: a scan of one did nothing, silently. They have been removed from both. Ask us if you need one.</p></div><h2 id="amazon-s3" tabindex="-1">Amazon S3 <a class="header-anchor" href="#amazon-s3" aria-label="Permalink to “Amazon S3”">​</a></h2><p>Create a dedicated IAM user with a read-only policy on the bucket, and hand Arcsecond its access key, secret key, region and bucket name. The full click-by-click procedure is on its own page: <a href="./external-storage-aws">Creating a read-only IAM user for a bucket</a>.</p><h2 id="dropbox" tabindex="-1">Dropbox <a class="header-anchor" href="#dropbox" aria-label="Permalink to “Dropbox”">​</a></h2><ol><li>Log in to Dropbox and open the <a href="https://www.dropbox.com/developers/apps" target="_blank" rel="noreferrer">App Console</a>.</li><li>Create an app, with <strong>Scoped Access</strong> for the API.</li><li>Choose <strong>Full Dropbox</strong> for the type of access, and give Arcsecond a root folder instead: it restricts itself to that folder. (With <strong>App Folder</strong>, the data Arcsecond reads must be placed under that app&#39;s folder.)</li><li>Name the app and create it. In its <strong>Settings</strong> tab, scroll to <strong>OAuth2</strong> and click <strong>Generate</strong> next to <em>Generate access token</em>.</li><li>Paste that token, and the root folder, into the Dropbox credentials form in Arcsecond.</li></ol><h2 id="ftp" tabindex="-1">FTP <a class="header-anchor" href="#ftp" aria-label="Permalink to “FTP”">​</a></h2><p>Host, port, user, password and the root folder to index. FTP carries credentials in clear over the network: on anything but a trusted LAN, prefer <a href="#sftp">SFTP</a>.</p><h2 id="sftp" tabindex="-1">SFTP <a class="header-anchor" href="#sftp" aria-label="Permalink to “SFTP”">​</a></h2><p>Host, port, user and the root folder, plus either a password or a private key — with its passphrase if it has one. SFTP is the recommended way to reach a server you do not control the network to, and an SFTP storage can also hold the installation&#39;s new data.</p><h2 id="smb-windows-share" tabindex="-1">SMB / Windows share <a class="header-anchor" href="#smb-windows-share" aria-label="Permalink to “SMB / Windows share”">​</a></h2><p>The natural choice for an observatory NAS or a Windows machine sharing a folder: host, port (445 by default), the share name, the domain if the share is on one, user, password, and the root folder inside the share. An SMB storage can also hold the installation&#39;s new data.</p><h2 id="local-disk" tabindex="-1">Local disk <a class="header-anchor" href="#local-disk" aria-label="Permalink to “Local disk”">​</a></h2><p>A folder on the machine running Arcsecond.local is <strong>not attachable yet</strong>. Share the folder over SMB, or serve it over SFTP, and attach that instead.</p><h2 id="what-happens-once-a-storage-is-attached" tabindex="-1">What happens once a storage is attached <a class="header-anchor" href="#what-happens-once-a-storage-is-attached" aria-label="Permalink to “What happens once a storage is attached”">​</a></h2><p>Arcsecond.local scans and parses the content of an external storage exactly as it does for the data <a href="./storage">stored on the installation itself</a>:</p><ul><li>FITS and XISF headers are extracted, for searching in the web interface,</li><li>2D-image and 1D-spectrum previews are generated,</li><li>your list of <strong>follow-up targets</strong> is built from everything the installation holds and every storage you attached, each target with its data,</li><li>observing nights are reconstructed when the headers allow it.</li></ul><p><img src="'+s+'" alt="Overview of Observations &amp; Data" data-zoomable=""></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>An option to restrict the scan to specific folders is in the works.</p></div>',24)])])}const m=t(n,[["render",d]]);export{f as __pageData,m as default};
